  <section x-show="step===1" x-cloak class="glass rounded-3xl p-6 sm:p-8"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-sky-400">Pasul 1 din 4</p><h1 class="mt-2 text-2xl font-black">Unde construim proiectul?</h1><p class="mt-2 text-sm text-slate-500">Numele și locația vor identifica proiectul în portofoliul tău.</p><div class="mt-7 grid gap-5 sm:grid-cols-2"><label class="sm:col-span-2"><span class="field-label">Nume proiect *</span><input class="field" name="name" x-model="project.name" placeholder="Ex: Casa părinților – Brașov" required></label><label><span class="field-label">Județ *</span><select class="field" name="county" x-model="project.county" required><option value="">Alege județul</option><template x-for="county in counties"><option :value="county" x-text="county"></option></template></select></label><label><span class="field-label">Localitate *</span><input class="field" name="city" x-model="project.city" placeholder="Ex: Brașov" required></label><label><span class="field-label">Latitudine (opțional)</span><input class="field" type="number" step="0.000001" name="latitude" x-model="project.latitude" placeholder="45.6579"></label><label><span class="field-label">Longitudine (opțional)</span><input class="field" type="number" step="0.000001" name="longitude" x-model="project.longitude" placeholder="25.6012"></label><label class="sm:col-span-2"><span class="field-label">Observații</span><textarea class="field min-h-24" name="notes" x-model="project.notes" placeholder="Detalii despre acoperiș, branșament sau obiectivul proiectului"></textarea></label></div></section>
  <section x-show="step===2" x-cloak class="glass rounded-3xl p-6 sm:p-8"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-sky-400">Pasul 2 din 4</p><div class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><h1 class="mt-2 text-2xl font-black">Adaugă consumatorii</h1><p class="mt-2 text-sm text-slate-500">Puterea și orele zilnice determină dacă sistemul va face față.</p></div><button type="button" @click="addConsumer()" class="rounded-xl bg-sky-400 px-4 py-3 text-xs font-extrabold text-slate-950">＋ Consumator</button></div><div class="mt-6 flex flex-wrap gap-2"><template x-for="preset in presets"><button type="button" @click="addPreset(preset)" class="rounded-full border border-slate-700 px-3 py-2 text-[10px] font-bold text-slate-400 hover:border-sky-400" x-text="'+ '+preset.name"></button></template></div><div class="mt-5 space-y-3"><template x-for="(consumer,index) in consumers" :key="consumer.key"><div class="grid gap-3 rounded-2xl border border-slate-800 bg-slate-950/40 p-4 sm:grid-cols-[1.5fr_.7fr_.7fr_.55fr_.45fr_auto]"><label><span class="field-label">Denumire</span><input class="field-sm" :name="`consumers[${index}][name]`" x-model="consumer.name" required></label><label><span class="field-label">Putere W</span><input class="field-sm" type="number" min="1" :name="`consumers[${index}][nominal_power_w]`" x-model.number="consumer.power" required></label><label><span class="field-label">Pornire W</span><input class="field-sm" type="number" min="0" :name="`consumers[${index}][startup_power_w]`" x-model.number="consumer.startup"></label><label><span class="field-label">Ore/zi</span><input class="field-sm" type="number" min="0.01" max="24" step="0.25" :name="`consumers[${index}][hours_per_day]`" x-model.number="consumer.hours" required></label><label><span class="field-label">Prioritate</span><select class="field-sm" :name="`consumers[${index}][priority]`" x-model.number="consumer.priority"><option value="1">P1</option><option value="2">P2</option><option value="3">P3</option></select></label><div class="flex items-end gap-3 pb-2"><label class="flex items-center gap-1 text-[10px] text-slate-500"><input type="hidden" :name="`consumers[${index}][is_essential]`" value="0"><input type="checkbox" :name="`consumers[${index}][is_essential]`" value="1" x-model="consumer.essential" class="accent-sky-400"> EPS</label><button type="button" @click="removeConsumer(index)" class="text-rose-400">×</button></div></div></template></div><div class="mt-5 grid grid-cols-2 gap-3 rounded-2xl bg-sky-400/5 p-4 sm:grid-cols-3"><div><small class="text-slate-500">Consumatori</small><b class="block" x-text="consumers.length"></b></div><div><small class="text-slate-500">Putere conectată</small><b class="block text-sky-300" x-text="formatKw(totalPower)"></b></div><div><small class="text-slate-500">Consum estimat</small><b class="block text-amber-300" x-text="dailyLoad.toFixed(1)+' kWh/zi'"></b></div></div></section>
  <section x-show="step===3" x-cloak class="glass rounded-3xl p-6 sm:p-8"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-sky-400">Pasul 3 din 4</p><h1 class="mt-2 text-2xl font-black">Configurează sistemul fotovoltaic</h1><p class="mt-2 text-sm text-slate-500">Poți ajusta toate valorile înainte de a crea proiectul.</p><div class="mt-7 grid gap-6 lg:grid-cols-3"><div class="rounded-2xl border border-amber-400/15 bg-amber-400/5 p-5"><h2 class="mb-5 font-extrabold text-amber-300">☀ Panouri</h2><div class="space-y-4"><label><span class="field-label">Număr panouri</span><input class="field-sm" name="panel_count" type="number" min="1" x-model.number="system.panelCount" required></label><label><span class="field-label">Putere / panou</span><input class="field-sm" name="panel_power_w" type="number" min="50" x-model.number="system.panelPower" required></label><div class="grid grid-cols-2 gap-3"><label><span class="field-label">Orientare</span><select class="field-sm" name="orientation" x-model="system.orientation"><template x-for="o in ['N','NE','E','SE','S','SV','V','NV']"><option x-text="o"></option></template></select></label><label><span class="field-label">Unghi</span><input class="field-sm" name="tilt" type="number" min="0" max="90" x-model.number="system.tilt"></label></div><label><span class="field-label">Pierderi sistem %</span><input class="field-sm" name="losses_percent" type="number" min="0" max="60" x-model.number="system.losses"></label></div></div><div class="rounded-2xl border border-sky-400/15 bg-sky-400/5 p-5"><h2 class="mb-5 font-extrabold text-sky-300">◈ Invertor</h2><div class="space-y-4"><label><span class="field-label">Nume sistem</span><input class="field-sm" name="system_name" x-model="system.name" required></label><label><span class="field-label">Model invertor</span><input class="field-sm" name="inverter_name" x-model="system.inverterName" required></label><label><span class="field-label">Putere nominală W</span><input class="field-sm" name="inverter_power_w" type="number" min="100" x-model.number="system.inverterPower" required></label><div class="rounded-xl bg-slate-950/50 p-3 text-xs"><span class="text-slate-500">Putere PV instalată</span><b class="float-right text-amber-300" x-text="formatKw(pvPower)"></b></div></div></div><div class="rounded-2xl border border-violet-400/15 bg-violet-400/5 p-5"><h2 class="mb-5 font-extrabold text-violet-300">▣ Baterie</h2><input type="hidden" name="battery_enabled" value="0"><label class="mb-5 flex items-center justify-between text-sm"><span>Include baterie</span><input type="checkbox" name="battery_enabled" value="1" x-model="system.battery" class="size-5 accent-violet-400"></label><div class="space-y-4" :class="!system.battery&&'opacity-30 pointer-events-none'"><label><span class="field-label">Capacitate kWh</span><input class="field-sm" name="battery_capacity_kwh" type="number" step="0.01" x-model.number="system.batteryCapacity"></label><label><span class="field-label">Putere încărcare/descărcare W</span><input class="field-sm" name="battery_power_w" type="number" x-model.number="system.batteryPower"></label><label><span class="field-label">SOC inițial %</span><input class="field-sm" name="initial_soc" type="number" min="10" max="100" x-model.number="system.soc"></label></div></div></div></section>
  <section x-show="step===4" x-cloak class="glass rounded-3xl p-6 sm:p-8"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-sky-400">Pasul 4 din 4</p><h1 class="mt-2 text-2xl font-black">Verifică și creează proiectul</h1><div class="mt-7 grid gap-4 md:grid-cols-2"><div class="rounded-2xl bg-slate-950/50 p-5"><small class="text-slate-500">PROIECT</small><h2 class="mt-2 text-lg font-extrabold" x-text="project.name"></h2><p class="text-sm text-slate-500" x-text="project.city+', '+project.county"></p></div><div class="rounded-2xl bg-slate-950/50 p-5"><small class="text-slate-500">CONSUM</small><h2 class="mt-2 text-lg font-extrabold text-sky-300" x-text="formatKw(totalPower)+' conectați'"></h2><p class="text-sm text-slate-500" x-text="consumers.length+' consumatori · '+dailyLoad.toFixed(1)+' kWh/zi'"></p></div><div class="rounded-2xl bg-slate-950/50 p-5"><small class="text-slate-500">SISTEM SOLAR</small><h2 class="mt-2 text-lg font-extrabold text-amber-300" x-text="formatKw(pvPower)+' instalați'"></h2><p class="text-sm text-slate-500" x-text="system.panelCount+' × '+system.panelPower+' W · '+system.orientation+' '+system.tilt+'°'"></p></div><div class="rounded-2xl bg-slate-950/50 p-5"><small class="text-slate-500">STOCARE</small><h2 class="mt-2 text-lg font-extrabold text-violet-300" x-text="system.battery?system.batteryCapacity+' kWh':'Fără baterie'"></h2><p class="text-sm text-slate-500" x-text="system.inverterName+' · '+formatKw(system.inverterPower)"></p></div></div><div class="mt-6 rounded-2xl border border-emerald-400/15 bg-emerald-400/5 p-5 text-sm text-slate-400">După creare, EnerSim va analiza automat vârfurile de pornire, producția zilnică, puterea invertorului și autonomia de backup. Vei primi un verdict și recomandări concrete.</div></section>
  <div class="mt-6 flex items-center justify-between"><button type="button" x-show="step>1" @click="step--" class="rounded-xl border border-slate-700 px-5 py-3 text-sm font-bold text-slate-400">← Înapoi</button><span x-show="step===1"></span><button type="button" x-show="step<4" @click="next()" class="rounded-xl bg-sky-400 px-6 py-3 text-sm font-extrabold text-slate-950">Continuă →</button><button type="submit" x-show="step===4" :disabled="submitting" class="rounded-xl bg-violet-600 px-6 py-3 text-sm font-extrabold text-white shadow-sm disabled:opacity-50" x-text="submitting?'Se creează…':'Creează și simulează →'"></button></div>
 </form>
</div>
<script>window.projectWizard=()=>({step:1,submitting:false,counties:['Alba','Arad','Argeș','Bacău','Bihor','Brașov','București','Cluj','Constanța','Covasna','Dolj','Galați','Harghita','Iași','Ilfov','Maramureș','Mureș','Prahova','Sibiu','Suceava','Timiș','Vâlcea'],project:{name:'',county:'',city:'',latitude:'',longitude:'',notes:''},system:{name:'Sistem fotovoltaic principal',panelCount:6,panelPower:505,orientation:'S',tilt:35,losses:15,inverterName:'Deye Hybrid 5 kW',inverterPower:5000,battery:true,batteryCapacity:5.12,batteryPower:2500,soc:80},presets:[{name:'Frigider',power:120,startup:700,hours:8,priority:1,essential:true},{name:'Hidrofor',power:900,startup:2500,hours:.5,priority:1,essential:true},{name:'Boiler',power:2000,startup:0,hours:2,priority:3,essential:false},{name:'Mașină de spălat',power:1800,startup:2100,hours:1,priority:3,essential:false},{name:'Aer condiționat',power:1200,startup:1800,hours:5,priority:2,essential:false},{name:'Iluminat',power:100,startup:0,hours:6,priority:2,essential:true}],consumers:[],key:0,init(){this.addPreset(this.presets[0]);this.addPreset(this.presets[5]);},addConsumer(){this.consumers.push({key:++this.key,name:'Consumator nou',power:100,startup:0,hours:2,priority:2,essential:false})},addPreset(p){this.consumers.push({key:++this.key,...p})},removeConsumer(i){if(this.consumers.length>1)this.consumers.splice(i,1)},get totalPower(){return this.consumers.reduce((s,c)=>s+Number(c.power||0),0)},get dailyLoad(){return this.consumers.reduce((s,c)=>s+Number(c.power||0)*Number(c.hours||0)/1000,0)},get pvPower(){return Number(this.system.panelCount)*Number(this.system.panelPower)},formatKw(w){return Number(w)>=1000?(Number(w)/1000).toFixed(2)+' kW':Number(w)+' W'},next(){if(this.step===1&&(!this.project.name||!this.project.county||!this.project.city)){alert('Completează numele, județul și localitatea.');return}if(this.step===2&&!this.consumers.length){alert('Adaugă cel puțin un consumator.');return}this.step++}})</script>
